entry.string:
$ErrorActionPreference = 'Stop'
$ready = $false

for ($i = 1; $i -le 30; $i++) {
    try {
        $html = (Invoke-WebRequest -Uri $env:PARABANK_URL -UseBasicParsing -TimeoutSec 5).Content
        if ($html -match 'name="username"') {
            $ready = $true
            break
        }
    } catch {
        Write-Host "ParaBank not ready yet, attempt $i"
    }

    Start-Sleep -Seconds 3
}

if (-not $ready) {
    Get-Content "$env:PROJECT_DIR\target\parabank-cargo.log" -Tail 120 -ErrorAction SilentlyContinue
    throw "ParaBank did not become ready with the login form."
}

$ports = @(8080, 8205, 9001)
foreach ($port in $ports) {
    Get-NetTCPConnection -LocalPort $port -ErrorAction SilentlyContinue |
        Select-Object -ExpandProperty OwningProcess -Unique |
        ForEach-Object {
            Stop-Process -Id $_ -Force -ErrorAction SilentlyContinue
        }
}
